<div class="customer-modal-backdrop"><section class="customer-modal"><div class="customer-modal-header"><div><span class="modal-eyebrow"><?= e($service['service_code']) ?></span><h2><?= e($service['service_name']) ?></h2><span class="modal-code"><?= e($service['category_name']?:'-') ?></span></div><a class="customer-modal-close" href="index.php?page=admin&amp;section=services">&times;</a></div><div class="customer-modal-body"><span class="service-status service-status-<?= e($service['status']) ?>"><?= e(ucfirst($service['status'])) ?></span><div class="modal-detail-grid"><div><span>Service Code</span><strong><?= e($service['service_code']) ?></strong></div><div><span>Category</span><strong><?= e($service['category_name']?:'-') ?></strong></div><div><span>Price</span><strong>Rs. <?= number_format((float)$service['price'],2) ?></strong></div><div><span>Duration</span><strong><?= $service['duration_minutes']!==null?(int)$service['duration_minutes'].' min':'-' ?></strong></div><div><span>Description</span><strong><?= e($service['description']?:'-') ?></strong></div><div><span>Created</span><strong><?= e($service['created_at']) ?></strong></div></div></div><div class="customer-modal-footer"><form method="post" action="index.php?page=admin&amp;section=services-toggle"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="service_id" value="<?= (int)$service['id'] ?>"><button class="btn btn-light"><?= $service['status']==='active'?'Deactivate':'Activate' ?></button></form><a class="btn btn-danger" href="index.php?page=admin&amp;section=services-edit&amp;id=<?= (int)$service['id'] ?>">Edit Service</a></div></section></div>
